using BARANG.Core.Domain.Production;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace BARANG.Core.Infrastructure.Persistence.Configurations;
internal sealed class ProductionJobConfiguration:IEntityTypeConfiguration<ProductionJob>{public void Configure(EntityTypeBuilder<ProductionJob>b){b.ToTable("production_jobs",t=>{t.HasCheckConstraint("ck_production_jobs_plan","planned_end_utc IS NULL OR planned_start_utc IS NOT NULL AND planned_end_utc > planned_start_utc");t.HasCheckConstraint("ck_production_jobs_queue","queue_position >= 0");t.HasCheckConstraint("ck_production_jobs_quantity","quantity_completed IS NULL OR quantity_completed >= 0");});b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.CompanyId).HasColumnName("company_id");b.HasAlternateKey(x=>new{x.CompanyId,x.Id});b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.OrderItemId).HasColumnName("order_item_id");b.Property(x=>x.PrintOperationId).HasColumnName("print_operation_id");b.Property(x=>x.JobType).HasColumnName("job_type").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.Priority).HasColumnName("priority").HasConversion<string>().HasMaxLength(12);b.Property(x=>x.QueuePosition).HasColumnName("queue_position");b.Property(x=>x.AssignedOperatorUserId).HasColumnName("assigned_operator_user_id");b.Property(x=>x.AssignedEquipmentId).HasColumnName("assigned_equipment_id");b.Property(x=>x.PlannedStartUtc).HasColumnName("planned_start_utc");b.Property(x=>x.PlannedEndUtc).HasColumnName("planned_end_utc");b.Property(x=>x.StartedAtUtc).HasColumnName("started_at_utc");b.Property(x=>x.CompletedAtUtc).HasColumnName("completed_at_utc");b.Property(x=>x.FailureReason).HasColumnName("failure_reason").HasMaxLength(500);b.Property(x=>x.SuspensionReason).HasColumnName("suspension_reason").HasMaxLength(500);b.Property(x=>x.ArtworkVersionId).HasColumnName("artwork_version_id");b.Property(x=>x.FileVersionId).HasColumnName("file_version_id");b.Property(x=>x.QuantityCompleted).HasColumnName("quantity_completed").HasPrecision(18,4);b.Property(x=>x.ExecutionNotes).HasColumnName("execution_notes").HasMaxLength(1000);b.Property(x=>x.GenerationKey).HasColumnName("generation_key").HasMaxLength(100);b.Property(x=>x.ReproductionRequestId).HasColumnName("reproduction_request_id");b.Property(x=>x.SourceProductionJobId).HasColumnName("source_production_job_id");b.Property(x=>x.RootProductionJobId).HasColumnName("root_production_job_id");b.Property(x=>x.ReproductionDepth).HasColumnName("reproduction_depth");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.CompanyId,x.GenerationKey}).IsUnique();b.HasIndex(x=>new{x.CompanyId,x.Status,x.Priority,x.QueuePosition,x.PlannedStartUtc});b.HasIndex(x=>new{x.CompanyId,x.AssignedOperatorUserId,x.Status});b.HasIndex(x=>new{x.CompanyId,x.AssignedEquipmentId,x.Status});b.HasOne<Domain.Orders.Order>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Orders.OrderItem>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderItemId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Orders.OrderPrintOperation>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.PrintOperationId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Catalog.Equipment>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.AssignedEquipmentId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Security.ApplicationUser>().WithMany().HasForeignKey(x=>x.AssignedOperatorUserId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Files.ArtworkVersion>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ArtworkVersionId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Files.FileVersion>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.FileVersionId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class ProductionJobHistoryConfiguration:IEntityTypeConfiguration<ProductionJobHistory>{public void Configure(EntityTypeBuilder<ProductionJobHistory>b){b.ToTable("production_job_history");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.CompanyId).HasColumnName("company_id");b.Property(x=>x.ProductionJobId).HasColumnName("production_job_id");b.Property(x=>x.EventType).HasColumnName("event_type").HasMaxLength(40);b.Property(x=>x.ActorUserId).HasColumnName("actor_user_id");b.Property(x=>x.OccurredAtUtc).HasColumnName("occurred_at_utc");b.Property(x=>x.Summary).HasColumnName("summary").HasMaxLength(500);b.HasIndex(x=>new{x.CompanyId,x.ProductionJobId,x.OccurredAtUtc,x.Id});b.HasOne<ProductionJob>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ProductionJobId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Security.ApplicationUser>().WithMany().HasForeignKey(x=>x.ActorUserId).OnDelete(DeleteBehavior.Restrict);}}
